import { readFileSync, writeFileSync } from "node:fs";

const explanations = {
  "80ffee8e-c7f0-4f0d-800c-a7bb54915290": { // Herr Dr. Moosberger
    21: { kw: "allergrößtem", ex: `"mit allergrößtem Interesse" تعبير ثابت (باهتمام بالغ جداً)، وحرف الجر "mit" يحكم Dativ، والصفة (تفضيل مطلق معزز بـaller-) في حالة الجر المحايد بدون أداة تعريف تأخذ نهاية "-em". أما "allergrößte" و"allergrößten" لا تطابقان حالة الجر المحايد بدون أداة. المحفز النحوي: حرف الجر "mit" + اسم محايد "Interesse" يحددان نهاية "-em".`, gs: "صفة تفضيل مطلق بحالة الجر المحايد بدون أداة: allergrößtem" },
    22: { kw: "in dem", ex: `جملة نسبية يعود ضمير الوصل المدمج "in dem" على اسم محايد مفرد "Stellenangebot"، وحرف الجر "in" يدل على مضمون الإعلان. أما "an dem" و"auf dem" لا يناسبان تعبير "in einem Angebot suchen". المحفز النحوي: مضمون الإعلان يستدعي "in" مع ضمير الوصل المحايد.`, gs: "ضمير وصل محايد بحرف جر: in dem" },
    23: { kw: "so", ex: `"so...wie" تركيب مقارنة تساوٍ (بمثل هذا الشهرة كمتجركم)، حيث "so" تسبق الصفة "renommierten" و"wie" تليها لاحقاً (wie dem Ihrigen). أما "als" تُستخدم بعد صيغة المقارنة التفضيلية لا بعد صفة أساسية، و"wie" هنا خاطئة لأنها الجزء الثاني من التركيب لا الأول. المحفز النحوي: تركيب المقارنة المتساوية "so+صفة...wie" يحدد "so" في هذا الموضع.`, gs: "تركيب مقارنة متساوية: so...wie" },
    24: { kw: "zu können", ex: `"es reizt mich, etwas zu übernehmen" مع فعل شرطي معدِّل "können" يتطلب تركيب مصدرين متتاليين: "übernehmen zu können". أما "können" وحدها لا تكتمل صيغة "zu+Infinitiv" المطلوبة، و"könnte" صيغة مصرّفة لا تناسب سلسلة المصادر. المحفز النحوي: تعبير "es reizt mich, zu+Infinitiv" مع فعل شرطي مساعد يفرض "Infinitiv+zu können" في النهاية.`, gs: "تركيب مصدر مزدوج: übernehmen zu können" },
    25: { kw: "begann", ex: `"eine Lehre beginnen" (يبدأ تدريباً)، والفعل هنا في Präteritum (زمن السرد المكتوب الرسمي في السيرة الذاتية) بصيغة "begann". أما "beging" (من begehen: يرتكب/يحتفل بمناسبة) معنى مختلف تماماً، و"belief" (من belaufen: يبلغ/يصل إلى مبلغ) لا يناسب بدء تدريب. المحفز النحوي: المفعول به "eine dreijährige Schreinerlehre" يستدعي فعل "beginnen" بصيغة Präteritum "begann".`, gs: "فعل ثابت بصيغة Präteritum: eine Lehre begann" },
    26: { kw: "ein Jahr lang", ex: `"ein Jahr lang" تعبير زمني (لمدة عام كامل) يصف مدة عمل منتهية في الماضي (عملت لمدة عام، ثم التحقت بالجامعة لاحقاً). أما "durch ein Jahr" ليس تعبيراً قياسياً، و"seit einem Jahr" (منذ عام) يصف بداية مستمرة حتى الحاضر وليس مدة منتهية. المحفز النحوي: وصف مدة عمل منتهية (تلاها التحاق بالجامعة) يستدعي "ein Jahr lang".`, gs: "تعبير مدة زمنية منتهية: ein Jahr lang" },
    27: { kw: "entdeckte", ex: `"seine Liebe zu etwas entdecken" تعبير ثابت (يكتشف شغفه بشيء)، مناسب لاكتشاف اهتمام جديد أثناء الدراسة. أما "erfand" (يخترع) لا يناسب اكتشاف مشاعر داخلية، و"merkte" (لاحظ) أضعف دلالياً. المحفز النحوي: التعبير الثابت "seine Liebe entdecken" يحدد الفعل.`, gs: "تعبير ثابت: seine Liebe zu etwas entdecken" },
    28: { kw: "Während", ex: `"Während" حرف جر زمني يحكم Genitiv ويعني "أثناء/خلال" (خلال فترة عملي ودراستي اكتسبت معرفة واسعة). أما "Dabei" (في هذا الصدد) ظرف لا حرف جر يحكم اسماً، و"Inzwischen" (في هذه الأثناء) ظرف مستقل أيضاً لا يحكم اسماً تالياً بحالة جر. المحفز النحوي: وجود اسمين في حالة الجر بعد الفجوة (meiner Berufstätigkeit und meines Studiums) يستدعي حرف الجر "Während".`, gs: "حرف جر زمني يحكم Genitiv: Während" },
    29: { kw: "sowohl ... als auch", ex: `"sowohl in Nordeuropa als auch in Südeuropa" أداة ربط مزدوجة تجمع منطقتين معاً (معرفة شاملة لكلتيهما). أما "teils...teils" توزيع جزئي غير مكتمل، و"weder...noch" نفي مزدوج يستبعد كليهما. المحفز النحوي: الجمع الكامل بين منطقتين يستدعي "sowohl...als auch".`, gs: "أداة ربط مزدوجة جامعة: sowohl...als auch" },
    30: { kw: "auf Ihre Anzeige zu antworten", ex: `"sich entschließen, zu+Infinitiv" تركيب ثابت (يقرر أن...)، والفعل "antworten" يتبعه حرف الجر "auf" (auf etwas antworten)، فالترتيب الصحيح "auf Ihre Anzeige zu antworten". أما بدون "zu" لا يكتمل التركيب، و"um...zu" تضيف غرضية زائدة غير مطلوبة مع "sich entschließen". المحفز النحوي: التعبير الثابت "sich entschließen, zu+Infinitiv" يحدد "zu antworten" دون "um" زائدة.`, gs: "تعبير ثابت + zu-Infinitiv: sich entschließen, zu..." },
  },
  "74c45095-393b-482c-8dac-8e55b739e34c": { // Herr Martini Original
    21: { kw: "zu", ex: `"zu einer Studienreise" تعبير ثابت يعني "بخصوص/بشأن رحلة دراسية" (استفساركم بشأن الرحلة)، وحرف الجر "zu" يدل على موضوع الطلب. أما "an" و"von" لا يشكلان هذا التعبير الثابت مع "Anfrage...zu" بنفس المعنى الرسمي. المحفز النحوي: التعبير الرسمي "Anfrage zu etwas" (استفسار بخصوص شيء) يحدد "zu".`, gs: "تلازم لفظي رسمي: Anfrage zu" },
    22: { kw: "kommenden", ex: `"im kommenden Oktober" صفة تصف الشهر المستقبلي القادم، مناسبة لوصف رحلة مخطط لها. أما "ankommenden" (من ankommen: يصل) لا معنى له مع اسم شهر، و"gekommenen" (Partizip II من kommen بصيغة الماضي) يصف حدثاً منتهياً لا مستقبلياً. المحفز النحوي: وصف رحلة مستقبلية مخططة يستدعي الصفة "kommenden" (القادم).`, gs: "صفة مستقبلية: kommenden Oktober" },
    23: { kw: "nach", ex: `"nach strengen Kriterien auswählen" تعبير ثابت يعني "يختار وفقاً لمعايير صارمة"، وحرف الجر "nach" يدل على المعيار المُتبع. أما "aus" (من) و"mit" (مع) لا يناسبان هذا التعبير الثابت للاختيار وفق معايير. المحفز النحوي: التعبير الثابت "nach Kriterien auswählen" يحدد "nach".`, gs: "تلازم لفظي: nach Kriterien auswählen" },
    24: { kw: "bieten", ex: `"etwas anbieten" فعل مركب منفصل يعني "يُقدّم/يعرض" (العائلات تقدم نصف إقامة)، والبادئة "an" تنتقل لنهاية الجملة (bieten...an). أما "fordern" (يطالب) معنى معاكس (الطلب لا التقديم)، و"nehmen" (يأخذ) أيضاً معاكس. المحفز النحوي: العائلات المضيفة تقدم (لا تطلب) الإقامة، وهذا يحدد "anbieten".`, gs: "فعل مركب منفصل: anbieten" },
    25: { kw: "so dass", ex: `"so dass" أداة ربط نتيجية (بحيث/لدرجة أن) تصف نتيجة القرب من المدرسة (قريبة بحيث يمكن الوصول سيراً خلال 10 دقائق). أما "weil" (لأن) سببية عكسية الاتجاه، و"wenn" (إذا/عندما) شرطية لا نتيجية. المحفز النحوي: وصف نتيجة مترتبة على القرب المكاني يستدعي "so dass".`, gs: "أداة ربط نتيجية: so dass" },
    26: { kw: "Gemeinsam mit", ex: `"gemeinsam mit jemandem" تعبير ثابت في بداية الجملة يعني "بالاشتراك مع" (يُنفَّذ برنامج الترفيه بالاشتراك مع طلاب المدرسة الشريكة). أما "Verbunden von" ليس تعبيراً قياسياً بهذا الشكل، و"Zusammen neben" (معاً بجانب) تركيب غير طبيعي. المحفز النحوي: وصف تنفيذ نشاط بمشاركة مجموعة أخرى يستدعي التعبير الثابت "gemeinsam mit".`, gs: "تعبير ثابت: gemeinsam mit" },
    27: { kw: "der Besuch", ex: `"der Besuch der Gemäldegalerie" اسم فاعل (زيارة المعرض) مناسب كموضوع للجملة (dazu gehört der Besuch = من بين ذلك زيارة المعرض)، وهو الاسم القياسي لوصف نشاط زيارة معلم. أما "die Ansicht" (وجهة النظر/الرأي، أو النظرة) لا يناسب سياق النشاط السياحي، و"das Betrachten" (التأمل/النظر إلى) فعل مصدري أضعف من الاسم الفعلي المتعارف عليه "Besuch" لوصف الزيارة الفعلية. المحفز النحوي: وصف نشاط زيارة معلم سياحي يستدعي الاسم القياسي "der Besuch".`, gs: "اسم فعل قياسي للزيارة: der Besuch" },
    28: { kw: "ist geplant", ex: `الجملة بصيغة المبني للمجهول الحالتي (Zustandspassiv: sein+Partizip II) تصف حالة تخطيط قائمة (زيارة الإذاعة مخططة أيضاً)، بخلاف "werden+Partizip II" الذي يصف عملية جارية. أما "hat geplant" (نحن خططنا، مبني للمعلوم) يغيّر الفاعل النحوي، و"wird geplant haben" (المستقبل التام، سيكون قد خُطط) زمن غير مناسب هنا. المحفز النحوي: وصف حالة تخطيط قائمة (لا عملية جارية) يستدعي "ist geplant".`, gs: "مبني للمجهول حالتي: ist geplant (Zustandspassiv)" },
    29: { kw: "besprochen", ex: `"etwas besprechen" (يناقش موضوعاً)، وفي صيغة المبني للمجهول (werden+Partizip II sollen: besprochen werden sollen = ينبغي مناقشتها)، والفعل "besprechen" في Partizip II هو "besprochen". أما "gesprochen" (من sprechen: يتحدث، فعل غير متعدٍ لا يحمل مفعولاً به مباشراً كـ"Aspekte") لا يناسب، و"versprochen" (يَعِد بشيء) معنى مختلف تماماً. المحفز النحوي: المفعول به "die verschiedenen Aspekte" (مواضيع تُناقَش) يستدعي الفعل المتعدي "besprechen".`, gs: "Partizip II لفعل متعدٍ في مبني للمجهول: besprechen → besprochen" },
    30: { kw: "haben", ex: `"einen Aufenthalt haben" تعبير ثابت (يقضي/يحظى بإقامة)، وفي زمن المضارع للتعبير عن أمل مستقبلي (نأمل أن تحظوا بإقامة لا تُنسى) بعد "hoffen, dass". أما "hatten" ماضٍ لا يناسب أملاً مستقبلياً، و"hätten" (Konjunktiv II) تفيد افتراضاً غير حقيقي لا أملاً حقيقياً بسيطاً. المحفز النحوي: التعبير الثابت "einen Aufenthalt haben" بعد "hoffen, dass" في سياق أمل حقيقي بسيط يستدعي المضارع "haben".`, gs: "تعبير ثابت بالمضارع بعد hoffen, dass: haben" },
  },
  "03f1a1a2-7c40-491c-b88b-90b984ff62a4": { // Herr Martini معدل
    21: { kw: "Ihrer", ex: `ضمير الملكية للمخاطب الرسمي (Sie-Form) بحالة الجر المؤنث (Genitiv بعد "vom 16. Juni...der Studienreise")، حيث "Ihrer Schulklasse" (فصلكم الدراسي) يصف ملكية الفصل للمخاطَب الرسمي. أما "Seiner" (له، غائب مذكر) و"Deiner" (لك، غير رسمي) لا يناسبان المخاطبة الرسمية بصيغة Sie. المحفز النحوي: المخاطبة الرسمية (Sehr geehrter Herr Martini) تستلزم ضمير الملكية الرسمي "Ihr" مُصرَّفاً هنا كـ"Ihrer" (مؤنث، جر).`, gs: "ضمير ملكية رسمي مؤنث بحالة الجر: Ihrer" },
    22: { kw: "kommenden", ex: `"im kommenden Oktober" صفة تصف الشهر المستقبلي القادم. أما "ankommenden" لا معنى له مع اسم شهر، و"gekommenden" ليست صيغة صحيحة نحوياً أصلاً (خطأ إملائي/تصريفي). المحفز النحوي: وصف رحلة مستقبلية يستدعي "kommenden".`, gs: "صفة مستقبلية: kommenden Oktober" },
    23: { kw: "nach", ex: `"nach strengen Kriterien auswählen" تعبير ثابت (يختار وفق معايير صارمة). أما "aus" و"mit" لا يناسبان هذا التعبير. المحفز النحوي: التعبير الثابت يحدد "nach".`, gs: "تلازم لفظي: nach Kriterien auswählen" },
    24: { kw: "bieten", ex: `"etwas anbieten" فعل مركب منفصل (العائلات تقدم نصف إقامة)، والبادئة "an" تنتقل للنهاية. أما "fordern" و"nehmen" معنى معاكس. المحفز النحوي: التقديم (لا الطلب) يحدد "anbieten".`, gs: "فعل مركب منفصل: anbieten" },
    25: { kw: "so dass", ex: `"so dass" أداة ربط نتيجية (بحيث) تصف نتيجة القرب المكاني. أما "weil" سببية عكسية، و"wenn" شرطية. المحفز النحوي: النتيجة المترتبة على القرب تستدعي "so dass".`, gs: "أداة ربط نتيجية: so dass" },
    26: { kw: "gemeinsam mit", ex: `"gemeinsam mit jemandem" تعبير ثابت (بالاشتراك مع) في بداية الجملة. أما "verbunden von" و"zusammen neben" ليسا تعبيرين قياسيين. المحفز النحوي: وصف نشاط مشترك يستدعي "gemeinsam mit".`, gs: "تعبير ثابت: gemeinsam mit" },
    27: { kw: "der Besuch", ex: `"der Besuch der Gemäldegalerie" اسم فعل قياسي للزيارة (dazu gehört der Besuch). أما "die" وحدها ليست اسماً كاملاً (خيار ناقص)، و"das Betrachten" أضعف دلالياً من "Besuch" لوصف الزيارة الفعلية. المحفز النحوي: وصف زيارة معلم سياحي يستدعي "der Besuch".`, gs: "اسم فعل قياسي للزيارة: der Besuch" },
    28: { kw: "ist geplant", ex: `مبني للمجهول حالتي (sein+Partizip II) يصف حالة تخطيط قائمة (زيارة الإذاعة مخططة أيضاً). أما "hat geplant" يغيّر الفاعل، و"wird geplant haben" زمن غير مناسب. المحفز النحوي: حالة قائمة تستدعي "ist geplant".`, gs: "مبني للمجهول حالتي: ist geplant" },
    29: { kw: "besprochen", ex: `"etwas besprechen" في مبني للمجهول (besprochen werden sollen = ينبغي مناقشتها). أما "gesprochen" فعل غير متعدٍ لا يناسب، و"versprochen" معنى مختلف. المحفز النحوي: المفعول به "Aspekte" يستدعي "besprechen→besprochen".`, gs: "Partizip II لفعل متعدٍ: besprechen → besprochen" },
    30: { kw: "haben", ex: `"einen Aufenthalt haben" بعد "hoffen, dass" في المضارع للتعبير عن أمل حقيقي. أما "hatten" ماضٍ، و"hätten" افتراض غير حقيقي. المحفز النحوي: الأمل الحقيقي البسيط يستدعي المضارع "haben".`, gs: "تعبير ثابت بالمضارع بعد hoffen, dass: haben" },
  },
  "801bfcf8-0ef8-4d25-8a3f-e42514768243": { // Herr Wenzel
    21: { kw: "für", ex: `"Dank für etwas" تعبير ثابت (شكراً على شيء)، وحرف الجر "für" يدل على موضوع الشكر (استفساركم). أما "auf" (نادراً ما يُستخدم بهذا المعنى مع Dank) و"wegen" (بسبب، سببية عامة أضعف من التعبير الثابت المحدد) لا يناسبان بنفس الدقة. المحفز النحوي: التعبير الثابت "Dank für" يحدد "für".`, gs: "تلازم لفظي: Dank für" },
    22: { kw: "jeweils", ex: `"jeweils am ersten Montag" ظرف يعني "في كل مرة/على التوالي" ويصف تكراراً منتظماً (كل شهر في أول اثنين تحديداً). أما "jeden" (كل، أداة تنكير لا ظرف مستقل بهذا الموضع النحوي)، و"jedoch" (لكن) أداة تضاد لا معنى تكراري. المحفز النحوي: وصف تكرار منتظم دقيق (يوم محدد كل مرة) يستدعي "jeweils".`, gs: "ظرف تكرار منتظم: jeweils" },
    23: { kw: "gewidmet", ex: `"einer Sache gewidmet sein" تعبير ثابت (مخصص/مكرَّس لشيء)، مناسب لوصف تخصيص كل أمسية لجانب ثقافي معين. أما "gedacht" (من denken، بمعنى مختلف: مُعَدّ لـ) أقل دقة هنا، و"geeignet" (مناسب لـ) يصف الملاءمة لا التخصيص. المحفز النحوي: التعبير الثابت "einem Aspekt gewidmet sein" يحدد "gewidmet".`, gs: "تعبير ثابت: einer Sache gewidmet sein" },
    24: { kw: "vorbereitende", ex: `الصفة "vorbereitend" (تحضيري) تصف الاسم "Treffen" (لقاءات، جمع محايد) بعد أداة تنكير غير محددة (mehrere)، فتُصرَّف بنهاية "-e" (تصريف مختلط جمع). أما "vorbereitend" (بدون نهاية) صيغة غير مصرّفة لا تصلح كنعت مباشر قبل اسم، و"vorbereiteten" (نهاية -en، تصريف ضعيف) لا يناسب "mehrere" التي تأخذ تصريفاً مختلطاً بنهاية "-e" في حالة النصب الجمع. المحفز النحوي: الصفة قبل اسم جمع بعد "mehrere" تتطلب نهاية "-e".`, gs: "تصريف صفة جمع بعد mehrere: vorbereitende" },
    25: { kw: "meisten", ex: `"die meisten unserer Mitglieder" تعبير كمي (معظم أعضائنا)، و"meisten" هنا صفة تفضيل مطلق مُسمّاة بعد أداة التعريف "die"، تصف أغلبية من مجموعة. أما "am meisten" ظرف تفضيل مطلق مستقل (الأكثر، يُستخدم مع أفعال لا أسماء بهذا الشكل)، و"meistens" ظرف تكرار (غالباً) لا كمية من مجموعة. المحفز النحوي: التعبير الكمي "die meisten+Genitiv" (معظم من...) يحدد الصيغة الاسمية "meisten".`, gs: "تعبير كمي: die meisten (+Genitiv)" },
    26: { kw: "entlang", ex: `"entlang der Route" حرف جر يعني "على طول" (رحلات على طول درب الشعراء الألمان)، مناسب لوصف مسار جغرافي ممتد. أما "gegenüber" (مقابل) يصف موقعاً معاكساً لا مساراً ممتداً، و"während" (أثناء) زمنية لا مكانية. المحفز النحوي: وصف رحلة تتبع مساراً جغرافياً محدداً يستدعي "entlang".`, gs: "حرف جر مكاني للمسار: entlang" },
    27: { kw: "auf", ex: `"auf den Spuren jemandes" تعبير ثابت يعني "على خطى شخص ما" (رحلة على خطى تشايكوفسكي)، شائع لوصف رحلات تتبع أثر شخصية تاريخية. أما "hinter" (خلف) و"neben" (بجانب) لا يشكلان هذا التعبير الثابت المجازي. المحفز النحوي: التعبير المجازي الثابت "auf den Spuren" يحدد "auf".`, gs: "تعبير ثابت مجازي: auf den Spuren" },
    28: { kw: "deren", ex: `جملة نسبية بحالة الملكية (Genitiv) تصف "مساعدتهم" (مساعدة الخبراء)، وتعود على اسم جمع "sachkundigen...Wissenschaftlern". ضمير الوصل بحالة الملكية للجمع هو "deren". أما "der" حالة الرفع لا تعبّر عن الملكية، و"dessen" حالة الملكية للمذكر/المحايد المفرد لا تناسب جمعاً. المحفز النحوي: وصف ملكية ("مساعدتهم") لاسم جمع يستدعي "deren".`, gs: "ضمير وصل بالملكية (جمع): deren" },
    29: { kw: "sofern", ex: `"sofern" أداة ربط شرطية تعني "بشرط أن/طالما" وتصف شرط إمكانية التبديل (يمكن التبديل بشرط أن يكون ذلك ممكناً تنظيمياً). أما "sogar" (حتى) تفيد التصعيد لا الشرط، و"sogleich" (على الفور) ظرف زمني لا أداة شرطية. المحفز النحوي: وصف شرط لإمكانية حدوث فعل يستدعي "sofern".`, gs: "أداة ربط شرطية: sofern" },
    30: { kw: "erreichbar", ex: `"erreichbar sein" تعبير ثابت يعني "يمكن الوصول إليه/التواصل معه" (المكتب متاح للتواصل من الاثنين للجمعة). أما "erhältlich" (متوفر للشراء، يُستخدم للسلع لا لخدمة تواصل)، و"wirksam" (فعّال/ساري المفعول) معنى مختلف تماماً. المحفز النحوي: وصف إمكانية التواصل مع المكتب يستدعي "erreichbar".`, gs: "تعبير ثابت لإمكانية التواصل: erreichbar" },
  },
  "d603954a-35c2-4af9-89f6-b159a511ca0a": { // Ida
    21: { kw: "auf", ex: `"sich auf etwas freuen" فعل انعكاسي ثابت يعني "يتطلع بشوق لشيء مستقبلي" (الوظيفة الجديدة والحياة في المدينة)، وحرف الجر الثابت معه "auf". أما "an" و"wegen" لا يشكلان هذا التعبير الثابت مع "sich freuen" بمعنى التطلع. المحفز النحوي: التعبير الثابت "sich freuen auf" يحدد "auf".`, gs: "فعل ثابت + حرف جر: sich freuen auf" },
    22: { kw: "hätte", ex: `"hätte...fahren können" صيغة Konjunktiv II افتراضية (كان بإمكاني أن أذهب، لكنني لم أفعل) تصف خياراً بديلاً لم يُتخذ في الماضي. أما "habe" (Perfekt حقيقي) يصف فعلاً حدث فعلاً، و"würde" (Konjunktiv II للمستقبل عادة) لا يتناسق مع "können" هنا بنفس الطبيعية في وصف إمكانية ماضية بديلة. المحفز النحوي: وصف خيار بديل افتراضي لم يحدث في الماضي يستدعي "hätte...können".`, gs: "Konjunktiv II لخيار بديل غير محقق: hätte...können" },
    23: { kw: "mich", ex: `"sich wohlfühlen" فعل انعكاسي، وفاعله "ich" يستدعي الضمير الانعكاسي المطابق "mich" (النصب، متكلم). أما "dich" (أنت) و"uns" (نحن) لا يتطابقان مع فاعل المتكلم المفرد "ich". المحفز النحوي: تطابق الضمير الانعكاسي مع الفاعل "ich" يحدد "mich".`, gs: "تطابق ضمير انعكاسي: ich → mich" },
    24: { kw: "ausgepackt hatte", ex: `أداة الربط "nachdem" تتطلب زمناً أسبق من الجملة الرئيسية (konnte، Präteritum)، فتُستخدم Plusquamperfekt في الجملة الثانوية: "ausgepackt hatte". أما "ausgepackt habe" (Perfekt) نفس زمن أو لاحق للجملة الرئيسية، و"auspackte" (Präteritum) نفس الزمن لا أسبق منه. المحفز النحوي: "nachdem"+فعل رئيسي في Präteritum يفرضان Plusquamperfekt سابقاً.`, gs: "توافق الأزمنة: nachdem + Plusquamperfekt" },
    25: { kw: "daran", ex: `"es liegt daran, dass..." تعبير ثابت (يعود السبب إلى أن...)، والضمير الظرفي "daran" (=an dem) يشير لسبب سيُذكر لاحقاً في جملة dass. أما "darauf" (=auf dem) يرتبط بأفعال أخرى، و"darin" (=in dem) لا يناسب هذا التعبير الثابت مع "liegen an". المحفز النحوي: التعبير الثابت "es liegt an etwas" يحدد الضمير الظرفي "daran".`, gs: "تعبير ثابت + ضمير ظرفي: es liegt daran, dass" },
    26: { kw: "miteinander", ex: `"miteinander ins Gespräch kommen" تعبير ثابت (يبدآن حديثاً معاً/يتبادلان الحديث)، ويصف تفاعلاً متبادلاً بين طرفين. أما "einander" (بعضهما البعض، بدون بادئة اتجاه) أقل دقة هنا، و"gegeneinander" (ضد بعضهما) معنى تنافسي معاكس تماماً. المحفز النحوي: وصف بدء حديث ودي متبادل يستدعي "miteinander".`, gs: "ضمير تبادلي: miteinander" },
    27: { kw: "als", ex: `"anders als" تعبير مقارنة اختلاف (مختلف عمّا كان قبل ثلاثة أشهر)، وحرف المقارنة بعد "anders" هو "als" حصراً. أما "denn" أداة سببية لا مقارنة، و"wenn" شرطية/زمنية لا تناسب المقارنة. المحفز النحوي: التعبير الثابت "anders als" يحدد "als".`, gs: "تعبير مقارنة اختلاف ثابت: anders als" },
    28: { kw: "obwohl", ex: `"obwohl" أداة ربط تنازلية (رغم أن) تصف تناقضاً بين الرضا عن الوظيفة والحاجة للعمل الإضافي. أما "trotzdem" (رغم ذلك) ظرف مستقل لا أداة ربط تُدخل جملة ثانوية، و"während" (بينما/أثناء) زمنية/تضادية أضعف من التنازل الصريح المقصود هنا. المحفز النحوي: التناقض بين الرضا والعمل الإضافي يستدعي أداة الربط التنازلية "obwohl".`, gs: "أداة ربط تنازلية لجملة ثانوية: obwohl" },
    29: { kw: "bei", ex: `"bei uns in der Abteilung" تعبير مكاني يعني "عندنا/لدينا في القسم"، وحرف الجر "bei" يدل على مكان/مجموعة الانتماء. أما "mit" (مع) و"zu" (إلى) لا يناسبان وصف الجو داخل قسم بهذا الشكل الثابت. المحفز النحوي: وصف أجواء العمل ضمن مجموعة (القسم) يستدعي "bei".`, gs: "حرف جر للانتماء المكاني: bei uns" },
    30: { kw: "eigentlich", ex: `"eigentlich" ظرف يعني "في الحقيقة/أصلاً" ويُستخدم في سؤال ودي عابر (كيف حالك في الحقيقة؟ - بعد أن تحدثت الكاتبة كثيراً عن نفسها). أما "hoffentlich" (نأمل) تفيد الأمل لا الاستفسار الفعلي، و"sicherlich" (بالتأكيد) تأكيد مسبق لا يناسب سؤالاً مفتوحاً. المحفز النحوي: الانتقال لسؤال حقيقي عن حال الصديقة بعد الحديث الطويل عن الذات يستدعي "eigentlich".`, gs: "ظرف انتقالي في سؤال ودي: eigentlich" },
  },
  "46c312c5-bf2c-4904-a965-004e4928fbb6": { // Igor
    21: { kw: "über", ex: `"sich über etwas freuen" فعل انعكاسي ثابت (يفرح بشيء حاضر/مُستلَم بالفعل: رسالتك)، وحرف الجر "über" يدل على سبب فرح مباشر بشيء تم استلامه. أما "mit" (مع) لا يشكل هذا التعبير، و"wegen" (بسبب) أعم وأقل دقة من التعبير الثابت المحدد. المحفز النحوي: الفرح بشيء مُستلَم فعلياً (الرسالة) يستدعي "sich freuen über".`, gs: "فعل ثابت + حرف جر: sich freuen über" },
    22: { kw: "außerdem", ex: `"außerdem" (بالإضافة إلى ذلك) أداة ربط إضافية تضيف سبباً ثانياً لتفضيل القطار (صديق للبيئة، وبالإضافة أرخص). أما "sonst" (وإلا/غير ذلك) تفيد بديلاً افتراضياً، و"weiterhin" (لا يزال/باستمرار) تفيد الاستمرارية لا الإضافة. المحفز النحوي: إضافة سبب ثانٍ لتفضيل سابق يستدعي "außerdem".`, gs: "أداة ربط إضافية: außerdem" },
    23: { kw: "fahren", ex: `"Zug fahren" تعبير ثابت يعني "يركب/يسافر بالقطار" (نستطيع ركوب القطار في 30 دولة). أما "kommen" (يأتي) لا يناسب وصف وسيلة النقل نفسها، و"nehmen" (يأخذ، عادة den Zug nehmen بأداة تعريف، وليس Zug fahren بدونها بهذا الشكل التعبيري تحديداً). المحفز النحوي: التعبير الشائع "Zug fahren" (بدون أداة تعريف، كتعبير عام عن السفر بالقطار) يحدد "fahren".`, gs: "تعبير ثابت: Zug fahren" },
    24: { kw: "da", ex: `"da" أداة ربط سببية (بما أن) في بداية الجملة تصف سبباً لإمكانية الحصول على تذكرة رخيصة (بما أننا دون 26 عاماً). أما "darum" و"deshalb" ظرفان استنتاجيان يفيدان النتيجة (لذلك) وليسا أداة ربط سببية تُدخل جملة ثانوية في البداية بهذا الترتيب (فعل الجملة الثانوية يجب أن يكون في النهاية: sind، وهذا يتطلب أداة ربط تابعة كـ"da" وليس ظرفاً مستقلاً). المحفز النحوي: بنية الجملة الثانوية (الفعل sind في وسط الجملة قبل الفاصلة، ثم جملة رئيسية تالية) تتطلب أداة ربط تابعة سببية "da".`, gs: "أداة ربط سببية تابعة: da" },
    25: { kw: "davon", ex: `"von etwas abhängen" تعبير ثابت (يعتمد على شيء)، والضمير الظرفي "davon" (=von dem) يشير لعامل سيُذكر لاحقاً (مدة السفر). أما "deshalb" و"damit" لا يرتبطان بفعل "abhängen von" الذي يحدد حرف الجر "von" حصراً. المحفز النحوي: التعبير الثابت "abhängen von" يحدد الضمير الظرفي "davon".`, gs: "تعبير ثابت + ضمير ظرفي: abhängen davon" },
    26: { kw: "gesprochen", ex: `"mit jemandem sprechen" (يتحدث مع شخص)، وفي زمن Perfekt (habe...gesprochen)، والفعل "sprechen" في Partizip II هو "gesprochen". أما "besprochen" (من besprechen: يناقش، فعل متعدٍ يحتاج مفعولاً به مباشراً وليس "mit meiner Tante" كحرف جر) لا يناسب البنية هنا، و"versprochen" (يَعِد) معنى مختلف تماماً. المحفز النحوي: التركيب "mit jmdm. sprechen" (بحرف الجر mit) يحدد الفعل غير المتعدي "sprechen→gesprochen" (لا الفعل المتعدي besprechen).`, gs: "Partizip II لفعل غير متعدٍ مع mit: sprechen → gesprochen" },
    27: { kw: "dass", ex: `"vorschlagen, dass..." تركيب ثابت (يقترح أن...)، وأداة الربط "dass" تُدخل الجملة التفسيرية لمضمون الاقتراح. أما "als" (عندما/بصفته) لا تناسب جملة اقتراح، و"wenn" (إذا/عندما) شرطية/زمنية لا تفسيرية. المحفز النحوي: التعبير الثابت "vorschlagen, dass" يحدد "dass".`, gs: "تعبير ثابت: vorschlagen, dass" },
    28: { kw: "sich", ex: `"sich freuen" فعل انعكاسي، وفاعله هنا "die beiden" (هما، غائب جمع)، فالضمير الانعكاسي المطابق "sich". أما "euch" (أنتم) و"uns" (نحن) لا يتطابقان مع فاعل الغائب الجمع "die beiden". المحفز النحوي: تطابق الضمير الانعكاسي مع الفاعل الغائب الجمع "die beiden" يحدد "sich".`, gs: "تطابق ضمير انعكاسي: die beiden → sich" },
    29: { kw: "der", ex: `"wegen" حرف جر يحكم حالة الجر (Genitiv)، والاسم "Sprachkenntnisse" (جمع مؤنث نوعاً، لكن كأداة تعريف جمع في حالة الجر Genitiv تأخذ "der" بغض النظر عن الجنس الأصلي للمفرد، لأن الجمع الألماني يوحّد أداة الجر/الملكية إلى "der"). أما "das" و"die" لا تناسبان حالة الجر الجمع بعد "wegen". المحفز النحوي: حرف الجر "wegen" يحكم Genitiv، وأداة التعريف الجمع في هذه الحالة هي "der".`, gs: "أداة تعريف جمع بحالة الجر بعد wegen: der" },
    30: { kw: "jedenfalls", ex: `"jedenfalls" ظرف يعني "على أي حال/في كل الأحوال" ويُستخدم لتأكيد شعور ثابت بغض النظر عن التفاصيل (أتطلع على أي حال لرحلتنا). أما "bestenfalls" (في أفضل الأحوال) يفيد شرطاً مثالياً غير مؤكد، و"keinesfalls" (بأي حال من الأحوال، نفي قاطع) معنى معاكس تماماً (عدم التطلع). المحفز النحوي: التعبير عن تطلع مؤكد بغض النظر عن الظروف يستدعي "jedenfalls".`, gs: "ظرف تأكيد عام: jedenfalls" },
  },
  "171c4f78-cb86-4f4c-9705-1c11dd07632e": { // Jens Fußballtrainer
    21: { kw: "lassen", ex: `"jemanden warten lassen" تعبير ثابت (يترك شخصاً ينتظر)، والفعل "lassen" هنا في صيغة المصدر لأنه يأتي بعد فعل شرطي/إرادي "will" (لا أريد أن أتركك تنتظر). أما "gelassen" (Partizip II) لا يناسب بعد "will" الذي يتطلب مصدراً، و"ließ" (Präteritum) صيغة مصرّفة لا مصدرية. المحفز النحوي: الفعل "will" يتطلب فعلاً ثانياً بصيغة المصدر، فالصحيح "lassen".`, gs: "فعل مصدر بعد فعل إرادي: will...lassen" },
    22: { kw: "weil", ex: `"weil" أداة ربط سببية (لأن) تصف سبباً لعدم رغبة الكاتب بتأخير الرد (لأنه يريد معرفة المزيد عن وظيفتك الجديدة). أما "denn" أيضاً سببية لكنها لا تُدخل جملة ثانوية بترتيب الفعل في النهاية (denn تربط جملتين رئيسيتين بترتيب عادي، بينما البنية هنا "weil ich...möchte" تضع الفعل في النهاية، وهذا نمط الجملة الثانوية التابعة الذي تفرضه "weil" لا "denn")، و"wenn" شرطية/زمنية لا سببية. المحفز النحوي: ترتيب الفعل في نهاية الجملة (möchte) يدل على جملة ثانوية تابعة، وهذا يستدعي "weil" لا "denn".`, gs: "أداة ربط سببية تابعة (فعل في النهاية): weil" },
    23: { kw: "als", ex: `"als Fußballtrainer" تعبير يصف صفة/دور (بصفتك مدرب كرة قدم)، حيث "als+اسم بدون أداة" يصف وظيفة أو دور حقيقي. أما "für" (من أجل) يصف الغرض لا الصفة، و"wie" (مثل) تشبيه مجازي لا وصف دور حقيقي فعلي. المحفز النحوي: وصف دور وظيفي حقيقي (وليس تشبيهاً) يستدعي "als".`, gs: "تعبير الصفة/الدور: als + اسم بدون أداة" },
    24: { kw: "dass", ex: `"nicht wissen, dass..." تركيب (لم أكن أعرف أنك...) وأداة الربط "dass" تُدخل جملة تفسيرية مؤكدة (حقيقة لم يكن يعرفها). أما "ob" تُدخل سؤالاً/شكاً وليس حقيقة مؤكدة اكتُشفت، و"wann" (متى) أداة استفهام عن التوقيت لا تناسب. المحفز النحوي: التعبير عن حقيقة مؤكدة مكتشفة يستدعي "dass" لا "ob" (التي تفيد الشك).`, gs: "أداة تفسيرية لحقيقة مؤكدة: dass" },
    25: { kw: "ziemlich", ex: `"ziemlich viel Stress" ظرف تدرّج (إلى حد كبير) يكثّف كمية الضغط. أما "eigentlich" (في الحقيقة/أصلاً) ظرف مختلف المعنى تماماً، و"unbedingt" (بأي ثمن) يصف إصراراً لا كمية. المحفز النحوي: تكثيف كمية الضغط (viel Stress) يستدعي ظرف الشدة "ziemlich".`, gs: "ظرف تدرّج يكثف كمية: ziemlich" },
    26: { kw: "beim", ex: `"beim Schulpraktikum" (bei+dem، مدمجة) حرف جر زمني/ظرفي يعني "أثناء التدريب المدرسي"، شائع لوصف فترة نشاط (beim+اسم نشاط = أثناء القيام بـ). أما "für" (من أجل) لا يصف فترة زمنية، و"während" (أثناء) تحكم Genitiv وتتطلب بنية مختلفة قليلاً (تُستخدم عادة أيضاً لكن الخيار الصحيح المحدد هنا هو "beim" وفق التركيب المُعطى). المحفز النحوي: وصف فترة نشاط محدد (التدريب) يستدعي التعبير الثابت "beim+اسم النشاط".`, gs: "تعبير ثابت لفترة نشاط: beim + اسم" },
    27: { kw: "durchzusetzen", ex: `"es nicht schaffen, sich durchzusetzen" تركيب ثابت (لا ينجح في فرض احترامه/سيطرته) يتطلب صيغة "zu+Infinitiv" بعد "schaffen"، والفعل المركب المنفصل "durchsetzen" يلتصق بـ"zu" في المنتصف (durchzusetzen) عند استخدامه بصيغة المصدر مع zu. أما "durchsetzen" بدون "zu" لا يكتمل تركيب "schaffen, zu+Infinitiv"، و"zu durchsetzen" ترتيب خاطئ (zu يجب أن يُدرَج بين البادئة والجذع: durch-zu-setzen وليس قبل الفعل كاملاً). المحفز النحوي: تعبير "schaffen, zu+Infinitiv" مع فعل منفصل يفرض إدراج "zu" بين البادئة والجذع: "durchzusetzen".`, gs: "zu مُدرَجة داخل فعل منفصل: durchzusetzen" },
    28: { kw: "was", ex: `"was" ضمير وصل غير محدد يعود على فكرة عامة (ما فعلوه فقط، بدون مرجع اسمي محدد سابق)، ويُستخدم بعد أفعال تصف سلوكاً غير محدد المرجع. أما "das" ضمير وصل يحتاج اسماً محدداً سابقاً يعود عليه، و"welches" ضمير وصل عادي أيضاً يحتاج مرجعاً اسمياً واضحاً. المحفز النحوي: غياب اسم محدد سابق (الفعل وصف سلوكاً عاماً "فعلوا ما أرادوا") يستدعي ضمير الوصل غير المحدد "was".`, gs: "ضمير وصل غير محدد المرجع: was" },
    29: { kw: "totalem", ex: `"in totalem Chaos" تعبير يصف حالة (في فوضى تامة)، وحرف الجر "in" مع اسم محايد بدون أداة تعريف يتطلب تصريفاً قوياً للصفة بنهاية "-em" في حالة الجر. أما "totalen" (نهاية -en) تناسب تصريفاً ضعيفاً (مع أداة تعريف)، و"totales" (نهاية -es) تناسب حالة الرفع/النصب لا الجر. المحفز النحوي: حرف الجر "in" (Dativ) + اسم محايد بدون أداة يفرضان نهاية "-em".`, gs: "صفة قوية بحالة الجر المحايد بدون أداة: totalem" },
    30: { kw: "mir", ex: `"sich etwas vorstellen" فعل انعكاسي يعني "يتخيل شيئاً"، وفاعله "ich" لكن هذا الفعل الانعكاسي المحدد "sich etwas vorstellen" (بمعنى التخيل الذهني لشيء) يحكم ضميراً انعكاسياً بحالة الجر (Dativ) وليس النصب (لأن "etwas" هو المفعول به المباشر بالنصب، والضمير الانعكاسي هنا يكون Dativ: sich[Dativ] etwas[Akkusativ] vorstellen). فالصحيح "mir" (جر، متكلم). أما "mich" (نصب) يتعارض مع وجود مفعول به مباشر آخر (etwas)، و"sich" (غائب) لا يتطابق مع الفاعل "ich". المحفز النحوي: الفعل الانعكاسي "sich(Dativ) etwas vorstellen" يتطلب ضميراً انعكاسياً بحالة الجر مع فاعل المتكلم "ich"، وهذا يحدد "mir".`, gs: "فعل انعكاسي بحالة الجر (مع مفعول به مباشر آخر): sich(Dativ) etwas vorstellen" },
  },
  "067c186b-1365-4d5a-9233-2e54fa7377f9": { // Judith oder Lina
    21: { kw: "Hoffentlich", ex: `"Hoffentlich" ظرف يعني "نأمل أن/ليت" ويُستخدم في بداية جملة للتعبير عن أمل بحدوث شيء (نأمل أن تقرئي هذه الرسالة اليوم). أما "Zuversichtlich" (بثقة/متفائل) صفة/ظرف يصف حالة شخص لا أملاً في حدث، و"Möglichst" (قدر الإمكان) يُستخدم مع صفة أخرى لا كظرف مستقل للأمل. المحفز النحوي: التعبير عن أمل بحدث مستقبلي غير مؤكد في بداية الجملة يستدعي "Hoffentlich".`, gs: "ظرف أمل في بداية الجملة: Hoffentlich" },
    22: { kw: "nämlich", ex: `"nämlich" أداة توضيحية تُقدّم تفصيلاً/سبباً لما سبق (نريد أن نهدي زميلتنا إيلينا، وتحديداً بمناسبة تقاعدها). أما "vermutlich" (يُفترض/على الأرجح) يفيد الاحتمال لا التوضيح، و"bestimmt" (بالتأكيد) تأكيد لا توضيح سببي. المحفز النحوي: تقديم توضيح/سبب لما سبق يستدعي "nämlich".`, gs: "أداة توضيحية: nämlich" },
    23: { kw: "schon", ex: `"schon übermorgen" ظرف يعني "بالفعل/في وقت مبكر نسبياً" ويؤكد قرب الموعد (حفل الوداع هو بعد غد بالفعل، أي قريب جداً). أما "fast" (تقريباً) يصف اقتراباً غير مكتمل من زمن، و"beinahe" (تقريباً أيضاً، مرادف لـfast) نفس المعنى غير المناسب هنا. المحفز النحوي: التأكيد على قرب موعد محدد (بعد غد) يستدعي ظرف التقريب الزمني المؤكِّد "schon".`, gs: "ظرف تأكيد لقرب الزمن: schon" },
    24: { kw: "damit", ex: `"damit einverstanden sein" تعبير ثابت (يوافق على شيء)، والضمير الظرفي "damit" (=mit dem/das) يشير لموضوع الموافقة (شراء قسيمة وباقة ورد معاً). أما "dafür" (=für das) يرتبط بأفعال أخرى مثل "sich interessieren für"، و"dadurch" (بواسطة ذلك) يصف وسيلة لا موضوع موافقة. المحفز النحوي: التعبير الثابت "einverstanden sein mit" يحدد الضمير الظرفي "damit".`, gs: "تعبير ثابت + ضمير ظرفي: einverstanden sein damit" },
    25: { kw: "Als", ex: `"Als" أداة ربط زمنية لحدث ماضٍ واحد محدد (عندما جمعنا التبرعات آخر مرة)، تُستخدم مع Präteritum (hatten) لوصف حدث فريد في الماضي. أما "Wenn" تُستخدم للتكرار أو الحاضر/المستقبل، و"Wann" أداة استفهام لا ربط. المحفز النحوي: وصف حدث ماضٍ فريد ("آخر مرة") يستدعي "Als".`, gs: "أداة زمنية لحدث ماضٍ فريد: als" },
    26: { kw: "miteinander", ex: `"miteinander einkaufen gehen" تعبير يعني "يذهبان للتسوق معاً" ويصف نشاطاً مشتركاً بين شخصين (ميشائيل والكاتبة). أما "zueinander" (تجاه بعضهما) يصف اتجاهاً عاطفياً/سلوكياً لا نشاطاً مشتركاً، و"voneinander" (عن بعضهما) يصف انفصالاً أو معرفة متبادلة لا نشاطاً مشتركاً. المحفز النحوي: وصف نشاط مشترك (التسوق معاً) يستدعي "miteinander".`, gs: "ضمير تبادلي لنشاط مشترك: miteinander" },
    27: { kw: "kurz", ex: `"kurz vor der Feier" ظرف زمني يعني "قبل الحفل بوقت قصير" (يمكنك التوقيع قبل الحفل بقليل). أما "vor Kurzem" (منذ وقت قصير، ماضٍ) يصف زمناً ماضياً لا مستقبلياً، و"kürzlich" (مؤخراً، أيضاً ماضٍ) نفس المشكلة. المحفز النحوي: وصف نقطة زمنية قريبة من حدث مستقبلي (الحفل) يستدعي "kurz vor" لا الظروف الماضية.`, gs: "ظرف زمني للقرب من حدث مستقبلي: kurz vor" },
    28: { kw: "weshalb", ex: `"weshalb" أداة ربط نتيجية/سببية تعني "الأمر الذي بسببه" وتصف نتيجة لظرف سابق (كثرة إجازات الزملاء، الأمر الذي جعلني مشغولة جداً). أما "insofern" (بقدر ما/من هذه الناحية) أداة أضيق نطاقاً، و"deshalb" (لذلك) ظرف مستقل لا أداة ربط نسبية تصف نتيجة داخل الجملة بهذا الشكل المتصل. المحفز النحوي: وصف نتيجة مباشرة لظرف مذكور سابقاً داخل نفس الجملة يستدعي "weshalb".`, gs: "أداة ربط نتيجية نسبية: weshalb" },
    29: { kw: "vollkommen", ex: `"vollkommen neue Entwicklungen" ظرف تكثيف يعني "تماماً/كلياً جديدة" ويعزز صفة "neue". أما "sämtlich" (كل/جميع، أداة كمية شاملة لا ظرف تكثيف لصفة) لا يناسب موضعياً، و"erschöpfend" (شامل/مستفيض، يصف وصفاً تفصيلياً لا درجة الجدة). المحفز النحوي: تكثيف صفة "neue" (جديدة) يستدعي ظرف التكثيف "vollkommen".`, gs: "ظرف تكثيف لصفة: vollkommen" },
    30: { kw: "angenehmen", ex: `"einen angenehmen Tag wünschen" تعبير ثابت شائع (يتمنى يوماً سعيداً/ممتعاً)، وهو أشيع تعبير ختامي ودي. أما "passenden" (مناسب) لا يحمل نفس الدفء الودي في هذا السياق الختامي، و"bequemen" (مريح جسدياً، يُستخدم عادة لأشياء مادية كالكرسي لا لليوم بأكمله). المحفز النحوي: التعبير الختامي الودي الشائع "einen angenehmen Tag" يحدد "angenehmen".`, gs: "تعبير ختامي ودي ثابت: einen angenehmen Tag" },
  },
  "2e4cb5d1-1205-44af-b53c-8b845b21abbe": { // Julia
    21: { kw: "voneinander", ex: `"voneinander hören" تعبير ثابت يعني "يسمع كل طرف عن الآخر/يتواصلان" (لم نتواصل منذ أشهر). أما "miteinander" (معاً) يصف نشاطاً مشتركاً مباشراً أقوى من مجرد "سماع أخبار"، و"zueinander" (تجاه بعضهما) يصف اتجاهاً عاطفياً لا تواصلاً إخبارياً. المحفز النحوي: التعبير الثابت "voneinander hören" (تبادل الأخبار عن بعد) يحدد "voneinander".`, gs: "تعبير ثابت: voneinander hören" },
    22: { kw: "durch", ex: `"eine Rundreise durch Europa" تعبير ثابت (جولة عبر/خلال أوروبا)، وحرف الجر "durch" يصف التنقل عبر منطقة جغرافية واسعة. أما "über" (حول/عبر أيضاً لكن أقل دقة مع "Rundreise" تحديداً) و"von" (من) لا يناسبان هذا التعبير الثابت للجولات. المحفز النحوي: التعبير الثابت "eine Reise durch ein Gebiet" يحدد "durch".`, gs: "تعبير ثابت: eine Rundreise durch" },
    23: { kw: "Wie", ex: `"wie du weißt" تعبير ثابت يعني "كما تعلمين" ويُستخدم لتقديم معلومة مفترض أنها معروفة للمستلم مسبقاً. أما "weil" (لأن) سببية لا تناسب هذا التعبير التمهيدي، و"wenn" (إذا) شرطية لا تناسب أيضاً. المحفز النحوي: التعبير الثابت "wie du/Sie weißt" يحدد "wie".`, gs: "تعبير ثابت: wie du weißt" },
    24: { kw: "war", ex: `"war...begeistert" فعل الكينونة "sein" في زمن Präteritum يصف حالة ماضية بسيطة (لم يكن متحمساً في البداية)، مناسب لسرد الرسالة بالماضي البسيط. أما "wurde" (من werden، يصير/أصبح) يصف تحولاً/تغيراً وليس حالة ثابتة وصفية، و"würde" (Konjunktiv II) يفيد افتراضاً غير واقعي لا حالة ماضية حقيقية. المحفز النحوي: وصف حالة ماضية حقيقية (لم يكن متحمساً) يستدعي "war" (Präteritum من sein).`, gs: "فعل الكينونة الماضي لحالة وصفية: war" },
    25: { kw: "es", ex: `"es ist ruhig" تركيب غير شخصي يصف حالة عامة (الجو هادئ في الشركة)، والفاعل الشكلي الإلزامي هنا "es" (كما في "es regnet"). أما "er" (هو) و"man" (المرء) لا يناسبان وصف حالة عامة غير شخصية بهذا الشكل (لا يوجد فاعل حقيقي محدد، بل وصف حال). المحفز النحوي: التركيب غير الشخصي لوصف حالة عامة (الهدوء) يستدعي الفاعل الشكلي "es".`, gs: "فاعل شكلي لوصف حالة عامة: es" },
    26: { kw: "erste", ex: `"meine erste Station" الصفة الترتيبية "erste" (الأولى) بعد ضمير الملكية "meine" في حالة الرفع (فاعل الجملة: Amsterdam war meine erste Station)، فتُصرَّف بنهاية "-e" (تصريف ضعيف في حالة الرفع المؤنث بعد أداة/ضمير ملكية). أما "ersten" (نهاية -en) تناسب حالات أخرى (النصب/الجر)، و"erster" (نهاية -er) تناسب تصريفاً قوياً بدون أداة. المحفز النحوي: ضمير الملكية "meine" (مؤنث، رفع) قبل الصفة الترتيبية يفرض نهاية "-e".`, gs: "صفة ترتيبية بعد ضمير ملكية في حالة الرفع: erste" },
    27: { kw: "daran", ex: `"an etwas denken" تعبير ثابت (يفكر في شيء)، والضمير الظرفي "daran" (=an das) يشير لفكرة سيتم ذكرها لاحقاً (العودة للمكتب). أما "darüber" (=über das) يرتبط بأفعال أخرى (nachdenken über، sprechen über)، و"davon" (=von das) يرتبط أيضاً بأفعال مختلفة. المحفز النحوي: التعبير الثابت "denken an" يحدد الضمير الظرفي "daran".`, gs: "تعبير ثابت + ضمير ظرفي: denken daran" },
    28: { kw: "muss", ex: `"müssen" (يضطر/يجب عليه) يصف إلزاماً موضوعياً حتمياً (العودة للمكتب أمر لا مفر منه يوماً ما)، مناسب لنبرة عدم الرغبة في التفكير بأمر حتمي مزعج. أما "kann" (يستطيع) يفيد قدرة/إمكانية لا إلزاماً حتمياً، و"mag" (يرغب) يفيد رغبة، وكلاهما لا يناسب فكرة "العودة الحتمية غير المرغوبة". المحفز النحوي: وصف عودة حتمية غير مرغوبة يستدعي فعل الإلزام "müssen".`, gs: "فعل إلزام حتمي: müssen" },
    29: { kw: "mir", ex: `"jemandem kommt ein Gedanke" تعبير ثابت (تخطر فكرة لشخص ما)، والشخص هنا في حالة الجر (Dativ): "mir kam manchmal der Gedanke" (خطرت لي أحياناً فكرة). أما "ich" حالة الرفع (الفاعل النحوي هنا هو "der Gedanke" لا "ich")، و"mich" حالة النصب لا تناسب هذا التعبير الذي يتطلب Dativ. المحفز النحوي: التعبير الثابت "jemandem kommt ein Gedanke" يحدد حالة الجر "mir".`, gs: "تعبير ثابت بحالة الجر: mir kommt ein Gedanke" },
    30: { kw: "könnte", ex: `"könnte" (Konjunktiv II من können) تصف احتمالاً/تأملاً مستقبلياً غير مؤكد بنبرة متسائلة (ربما أبدأ شيئاً جديداً تماماً - مجرد فكرة تراودها). أما "bräuchte" (تحتاج) لا يناسب سياق البدء بشيء جديد كخيار، و"dürfte" (يُسمح لها) يفيد إذناً خارجياً لا تأملاً شخصياً حراً. المحفز النحوي: التأمل المتردد في احتمال مستقبلي (فكرة عابرة، لا خطة مؤكدة) يستدعي Konjunktiv II "könnte".`, gs: "Konjunktiv II لتأمل مستقبلي متردد: könnte" },
  },
  "c94ca060-b403-4762-8da3-3e5e0894546d": { // Julian
    21: { kw: "konntest", ex: `"können" (يستطيع) يصف قدرة تحققت في الماضي (أتمنى أنك تمكنت من الاستراحة جيداً)، وفي زمن Präteritum بصيغة "du"-Form: "konntest"، بعد فعل "hoffen, dass" في تركيب متوازٍ مع "hattest" السابقة (كلاهما ماضٍ Präteritum لوصف نفس الرحلة الماضية). أما "können" مصدر غير مصرّف، و"dürfen" (يُسمح له) يفيد إذناً لا قدرة على الاستراحة. المحفز النحوي: التوازي الزمني مع "hattest" (Präteritum) يفرض "konntest" بنفس الزمن.`, gs: "توافق زمني Präteritum: hattest...konntest" },
    22: { kw: "würde", ex: `"würde...fahren" صيغة Konjunktiv II تصف رغبة/أمنية غير محققة حالياً (أنا أيضاً أود السفر للبحر، لكن ليس لدي وقت)، مناسبة للتعبير عن رغبة مهذبة غير مؤكدة التحقق. أما "werden" (المستقبل الحقيقي البسيط) يصف خطة مؤكدة، و"wäre" (Konjunktiv II من sein) لا يناسب فعل "fahren" الذي يحتاج فعله المساعد الخاص به. المحفز النحوي: التعبير عن رغبة غير محققة (تتعارض مع الجملة التالية "لكن ليس لدي وقت") يستدعي "würde".`, gs: "Konjunktiv II لرغبة غير محققة: würde" },
    23: { kw: "für", ex: `"Zeit für etwas haben" تعبير ثابت (لديه وقت من أجل شيء)، وحرف الجر "für" يدل على الغرض/النشاط (لا وقت للعطلة). أما "als" (بصفته) و"von" (من) لا يشكلان هذا التعبير الثابت مع "Zeit haben". المحفز النحوي: التعبير الثابت "Zeit für etwas haben" يحدد "für".`, gs: "تلازم لفظي: Zeit für etwas haben" },
    24: { kw: "vielen", ex: `"nach vielen Jahren" تعبير زمني يعني "بعد سنوات عديدة"، وحرف الجر "nach" يحكم Dativ، والصفة "viel" (كثير) في حالة الجر الجمع بدون أداة تعريف تأخذ نهاية "-en": "vielen". أما "mehr" (أكثر، صيغة مقارنة غير مصرّفة أصلاً بهذا الشكل مع اسم مباشر) لا تناسب، و"viel" (بدون نهاية) صيغة غير مصرّفة لا تصلح كنعت مباشر قبل اسم جمع بحالة الجر. المحفز النحوي: حرف الجر "nach" (Dativ) + اسم جمع بدون أداة يفرضان نهاية "-en" على الصفة.`, gs: "صفة قوية بحالة الجر الجمع بدون أداة: vielen" },
    25: { kw: "gefallen", ex: `"jemandem gefallen" فعل يعني "يعجب شخصاً ما" (تعجبني البيوت ذات الهياكل الخشبية)، والفاعل النحوي هنا هو "die...Fachwerkhäuser" (جمع)، فيُصرَّف الفعل بصيغة الجمع "gefallen". أما "gefällt" (مفرد) لا يطابق الفاعل الجمع، و"mögen" (فعل مختلف، يُستخدم بصيغة أخرى: ich mag، وليس بهذا التركيب مع الفاعل المفعول به المقلوب mir gefallen). المحفز النحوي: الفاعل الجمع "Fachwerkhäuser" يفرض تصريف الفعل بصيغة الجمع "gefallen".`, gs: "تطابق الفعل مع الفاعل الجمع: Fachwerkhäuser gefallen" },
    26: { kw: "denn", ex: `"denn" أداة عطف سببية تربط جملتين رئيسيتين (أمشي في المنطقة المشاة، لأن هناك محلات ومقاهي كثيرة)، وترتيب الفعل بعدها يبقى عادياً (لا قلب ترتيب، بخلاف "weil" التي تضع الفعل في النهاية). أما "als" (عندما) زمنية لا سببية، و"wenn" (إذا/عندما) شرطية/زمنية أيضاً. المحفز النحوي: ترتيب الفعل العادي بعد الفجوة (dort gibt es) يدل على جملة رئيسية، وهذا يستدعي أداة العطف "denn" لا "weil" التابعة.`, gs: "أداة عطف سببية لجملة رئيسية (فعل بترتيب عادي): denn" },
    27: { kw: "wenn", ex: `"wenn du willst" تعبير شرطي شائع (إذا أردت/إن رغبت) يقدم عرضاً مشروطاً بإرادة المخاطَب. أما "außerdem" (بالإضافة إلى ذلك) ظرف إضافي لا شرطي، و"da" (بما أن) سببية وليست شرطية بنفس المرونة العرضية هنا. المحفز النحوي: تقديم عرض مشروط برغبة المخاطَب يستدعي الأداة الشرطية "wenn".`, gs: "أداة شرطية لعرض مشروط: wenn" },
    28: { kw: "dann", ex: `"dann" ظرف يعني "حينئذ/عندئذ" ويربط بجملة شرطية سابقة ضمنية (لو زرتني الشهر القادم، فستكون ضغوط الانتقال قد انتهت حينها)، شائع كبداية جملة تصف نتيجة زمنية لشرط. أما "wenn" (إذا) أداة شرطية تُستخدم لتقديم الشرط لا لبدء نتيجته، و"denn" (لأن) سببية لا نتيجة زمنية. المحفز النحوي: بدء جملة تصف نتيجة مترتبة على دعوة سابقة يستدعي الظرف الرابط "dann".`, gs: "ظرف نتيجة زمنية: dann" },
    29: { kw: "ausgeräumter", ex: `"ausgeräumte Kisten" صفة تصف صناديق مُفرَّغة من محتواها، وبعد النفي "nicht" وأداة تنكير غير محددة جمع، تُصرَّف الصفة بتصريف مختلط/قوي بنهاية "-er" في حالة النصب الجمع (eine große Anzahl nicht ausgeräumter Kisten). أما "entladener" (من entladen، يُستخدم عادة لشحنات/بطاريات لا صناديق منزلية بهذا المعنى الشائع)، و"entleerter" (مُفرَّغ، أقرب لكن أقل شيوعاً مع "Kisten" تحديداً من "ausgeräumt" الشائعة جداً في سياق التفريغ المنزلي). المحفز النحوي: وصف صناديق لم تُفرَّغ بعد بعد الانتقال يستدعي الصفة الشائعة "ausgeräumt" في تصريفها الصحيح.`, gs: "صفة شائعة للتفريغ المنزلي بتصريف الجمع: ausgeräumter" },
    30: { kw: "weil", ex: `"weil" أداة ربط سببية تابعة (لأن) تفسر سبب الحظ في الشقة الجديدة (لأنها واسعة ومركزية)، وترتيب الفعل في نهاية الجملة الثانوية ("ist" في نهاية الجملة) يؤكد هذا. أما "so dass" (بحيث) نتيجية عكسية الاتجاه المنطقي هنا، و"zu" لا تشكل أداة ربط سببية. المحفز النحوي: ترتيب الفعل في نهاية الجملة الثانوية (sie geräumig...ist) يدل على "weil".`, gs: "أداة ربط سببية تابعة (فعل في النهاية): weil" },
  },
};

