const passageTranslations = {
  "80ffee8e-c7f0-4f0d-800c-a7bb54915290": "السيد الدكتور موسبيرغر المحترم،\n\nقرأت باهتمام بالغ جداً إعلان وظيفتكم في صحيفة إيسن، الذي تبحثون فيه عن موظفة بدوام جزئي في متجر التحف الخاص بكم. يشدني تحمل مهمة ذات مسؤولية في متجر مرموق مثل متجركم. بعد إتمامي الثانوية العامة في مدرسة كرايس الثانوية في فيلبرت، بدأت تدريباً مهنياً لمدة ثلاث سنوات كنجارة لدى شركة آيشلبورر وشركاه، والتحقت بمدرسة كرايس المهنية في فيلبرت. بعد إتمام تدريبي المهني بنجاح، عملت لمدة عام لدى شركة شتوتس وشركاه لتصميم الأثاث في دوسلدورف. بعدها التحقت بجامعة العلوم التطبيقية في كولن في قسم تصميم الأثاث واكتشفت حبي للقطع الأثرية القديمة. تخصصي هو الترميم الدقيق للأثاث العتيق، خاصة من طرازي بيدرماير وآر نوفو. خلال عملي ودراستي تمكنت من اكتساب معرفة واسعة فيما يتعلق بأنماط الأثاث وفن الصناعة في مختلف الحقب، سواء في شمال أوروبا أو جنوبها. تتيح لي دراستي وقتاً كافياً لتولي وظيفة بدوام جزئي تتناسب أيضاً مع قدراتي المهنية وميولي. لهذا السبب قررت الرد على إعلانكم، وأتقدم للوظيفة بدوام جزئي التي تعرضونها. أتطلع إلى مقابلة شخصية.\n\nمع خالص التحيات،\nسابينه هولتسينغر",
  "74c45095-393b-482c-8dac-8e55b739e34c": "السيد مارتيني المحترم،\n\nشكراً جزيلاً على استفساركم بتاريخ 16 يونيو بشأن الرحلة الدراسية لفصلكم إلى فرانكفورت في أكتوبر القادم.\n\nالإقامة لدى عائلات ألمانية مضيفة ممكنة من حيث المبدأ. يتم اختيار العائلات بعناية من قبلنا وفق معايير صارمة تجدونها في الكتيب الإرشادي المرفق في الصفحات 15 إلى 17. يمكن استضافة طالب أو طالبين لكل عائلة مضيفة. تقدم عائلاتنا المضيفة نصف إقامة، أي عادة إفطار وعشاء. تسكن جميع العائلات بالقرب من المدرسة، بحيث يمكن قطع الطريق من السكن إلى الدروس سيراً خلال 10 دقائق كحد أقصى.\n\nمن المخطط مرتين أسبوعياً حضور دروس مدرستكم الشريكة في فرانكفورت، مدرسة هاينريش بول، في مواد الجغرافيا والفن والألمانية. لغة التدريس هي الألمانية. يُنفَّذ برنامج الترفيه والثقافة بالاشتراك مع طلاب المدرسة الشريكة.\n\nمن ضمن ذلك مثلاً زيارة معرض اللوحات 'شتيديل'، ومتحف الحرف اليدوية، والمتحف البريدي الألماني. كما أن زيارة الإذاعة الهسية مخططة أيضاً. تُقام أمسيات ثقافية كل ثلاثاء وجمعة، ينبغي مناقشة الجوانب والاختلافات المختلفة بين الثقافة الألمانية والإيطالية خلالها.\n\nستجدون مزيداً من المعلومات في الكتيب المرفق. نأمل أن تحظوا أنتم وفصلكم بإقامة غنية بالتجارب ولا تُنسى في فرانكفورت. لأي استفسارات إضافية يرجى التواصل معنا.\n\nمع خالص التحيات\nسيبيله لاوترباخر\nمؤسسة التبادل الطلابي فرانكفورت",
  "03f1a1a2-7c40-491c-b88b-90b984ff62a4": "السيد مارتيني المحترم،\n\nشكراً جزيلاً على استفساركم بتاريخ 16 يونيو بشأن الرحلة الدراسية لفصلكم إلى فرانكفورت في أكتوبر القادم.\n\nالإقامة لدى عائلات ألمانية مضيفة ممكنة من حيث المبدأ. يتم اختيار العائلات بعناية من قبلنا وفق معايير صارمة تجدونها في الكتيب الإرشادي المرفق في الصفحات 15 إلى 17. يمكن استضافة طالب أو طالبين لكل عائلة مضيفة. تقدم عائلاتنا المضيفة نصف إقامة، أي عادة إفطار وعشاء. تسكن جميع العائلات بالقرب من المدرسة، بحيث يمكن قطع الطريق من السكن إلى الدروس سيراً خلال 10 دقائق كحد أقصى.\n\nمن المخطط مرتين أسبوعياً حضور دروس مدرستكم الشريكة في فرانكفورت، مدرسة هاينريش بول، في مواد الجغرافيا والفن والألمانية. لغة التدريس هي الألمانية. يُنفَّذ برنامج الترفيه والثقافة بالاشتراك مع طلاب المدرسة الشريكة.\n\nمن ضمن ذلك مثلاً زيارة معرض اللوحات 'شتيديل'، ومتحف الحرف اليدوية، والمتحف البريدي الألماني. كما أن زيارة الإذاعة الهسية مخططة أيضاً. تُقام أمسيات ثقافية كل ثلاثاء وجمعة، ينبغي مناقشة الجوانب والاختلافات المختلفة بين الثقافة الألمانية والإيطالية خلالها.\n\nستجدون مزيداً من المعلومات في الكتيب المرفق. نأمل أن تحظوا أنتم وفصلكم بإقامة غنية بالتجارب ولا تُنسى في فرانكفورت. لأي استفسارات إضافية يرجى التواصل معنا.\n\nمع خالص التحيات\nسيبيله لاوترباخر\nمؤسسة التبادل الطلابي فرانكفورت",
  "801bfcf8-0ef8-4d25-8a3f-e42514768243": "السيد فينتسل المحترم،\n\nشكراً جزيلاً على استفساركم بخصوص أنشطة رابطة الثقافة. اهتمامنا الرئيسي هو إثراء الحياة الثقافية ودعم المبادرات الثقافية. يُقام لأعضائنا مرة شهرياً - تحديداً في أول اثنين - أمسية ثقافية في مقرنا في فيلا إميليا. كل أمسية مخصصة لجانب ثقافي معين، من الشعر إلى الموسيقى وصولاً إلى المسرح.\n\nبالإضافة إلى ذلك نزور بانتظام عروضاً مسرحية داخل ألمانيا ولدينا لذلك عدة لقاءات تحضيرية. من المحتمل أن تهم رحلاتنا الدراسية معظم أعضائنا بشكل خاص. تقودنا هذه الرحلات مثلاً على طول درب الشعراء الألمان من فرانكفورت إلى فايمار، إلى سالتسبورغ والمزيد.\n\nهذا العام نقدم بالمناسبة رحلة مميزة جداً: على خطى تشايكوفسكي إلى روسيا. جميع رحلاتنا يرافقها خبراء موسيقى أو أدب أكفاء، يمكنكم بمساعدتهم توسيع معرفتكم الثقافية. كما يُراعى الراحة الخاصة عند اختيار وسائل النقل والإقامة.\n\nخدمة مميزة هي تبديل التذاكر. إذا كان لديكم تذاكر مسرحية ولا ترغبون في استخدامها، يمكنكم تبديلها لدينا مقابل تذاكر أخرى - بشرط أن يكون ذلك ممكناً تنظيمياً.\n\nسعر العضوية 200 يورو سنوياً للفرد الواحد أو 300 يورو للعضوية المزدوجة (شخصان، مثل الأزواج أو الأصدقاء). مقرنا متاح للتواصل من الاثنين إلى الجمعة من 9 إلى 12 ومن 14 إلى 17، ويسعدنا الرد على استفساراتكم. استمارة التسجيل مرفقة بهذه الرسالة.\n\nمع تحيات ثقافية حارة\nسابينه سينغر\nرابطة الثقافة",
  "d603954a-35c2-4af9-89f6-b159a511ca0a": "عزيزتي إيدا،\n\nمضت الآن ثلاثة أشهر منذ انتقلت إلى فرانكفورت. استغرق الأمر وقتاً طويلاً حتى استقررت هنا. في البداية لم أكن متحمسة إطلاقاً للوظيفة الجديدة والحياة في المدينة. حقيقة أنني انتقلت من أجل وظيفتي الجديدة أزعجتني قليلاً لفترة. كان بإمكاني أيضاً ركوب القطار يومياً بدلاً من البحث عن شقة قرب الشركة. في البداية لم أشعر بالراحة في شقتي الجديدة أيضاً. لكن بعد أن أفرغت صناديق الانتقال، تمكنت أخيراً من استكشاف المدينة بشكل صحيح.\nمنذ فترة أصبحت أحب فرانكفورت حقاً. ويعود ذلك بشكل رئيسي إلى أنني وجدت صديقة جديدة. تسكن آنابيل في نفس الشارع مثلي وقد تعرفنا في سوق للبضائع المستعملة في حينا. كانت تبيع هناك كتبها القديمة. عندما بدأنا الحديث معاً، اكتشفنا أن لدينا اهتمامات وهوايات متشابهة: تحب هي أيضاً الموضة غير التقليدية والفن الحديث ونذهب الآن بانتظام معاً إلى المسبح.\nتبدو حياتي الآن مختلفة تماماً عمّا كانت عليه قبل ثلاثة أشهر فقط. أنا راضية أيضاً عن وظيفتي الجديدة، رغم أنني كثيراً ما أعمل ساعات إضافية. لكن يسود في المقابل جو عمل ودي عندنا في القسم. الآن تحدثت كثيراً عن نفسي، لكنني لم أسألك بعد كيف حالك في الحقيقة. هل هناك جديد لديك؟ أتطلع لرسالتك القادمة!\n\nتحياتي الحارة\nصديقتك إميليا",
  "46c312c5-bf2c-4904-a965-004e4928fbb6": "عزيزي إيغور،\n\nشكراً جزيلاً على رسالتك، التي فرحت بها كثيراً. إنها فكرة رائعة حقاً أن نسافر معاً في الصيف! لكن هل تريد حقاً السفر بالسيارة؟ أفضل ركوب القطار، لأنه أصدق بيئياً وبالإضافة أرخص. أنا في الوقت الحالي قليلة المال مرة أخرى.\nيمكننا القيام برحلة إنترريل. مع بطاقة عالمية يمكننا ركوب القطار في 30 دولة أوروبية، ومتى وأينما أردنا - لكن ليس عندنا في ألمانيا. هنا يجب أن ندفع إضافياً. لكن المسافة إلى الحدود ليست بعيدة جداً بالنسبة لي. بما أننا لم نبلغ 26 عاماً بعد، يمكننا الحصول على البطاقة بسعر مناسب جداً. يعتمد السعر على مدة سفرنا. إذا فضلت زيارة دولة واحدة فقط، أقترح السفر إلى فرنسا. حينها سندفع أقل حتى مقابل تذكرة إنترريل. تحدثت أيضاً بالفعل مع عمتي في مرسيليا، واقترحت فوراً أن نقضي بضعة أيام لديها. ابنا عمي جيروم وماتيو، اللذان يدرسان في باريس، لديهما عطلة فصل دراسي وسيكونان هناك أيضاً. سيسعدان بالتجول معنا في المدينة، ويمكنهما بالتأكيد أن يريانا أشهر النوادي في المدينة. لا داعي للقلق بشأن معرفتك اللغوية، لأن كليهما يتحدثان الألمانية بشكل جيد جداً. ما رأيك؟ هل لديك اقتراحات أخرى؟ أتطلع بالفعل بشدة لرحلتنا المشتركة.\n\nإلى اللقاء قريباً\nتوماس",
  "171c4f78-cb86-4f4c-9705-1c11dd07632e": "مرحباً ينس،\n\nشكراً على رسالتك، من الجميل أن أسمع منك! يسعدني أنك بخير كثيراً، البدء من جديد تماماً في مدينة غريبة ليس بالأمر السهل حقاً...\nهذه المرة لا أريد أن أتركك تنتظر ردي طويلاً وأكتب مباشرة على عكس عادتي المعتادة.\nليس أقلها لأنني أرغب في معرفة المزيد عن وظيفتك الجديدة بصفتك مدرب كرة قدم للأطفال. لم أكن أعرف أنك متحمس لكرة القدم إلى هذا الحد!\nألم تكن سابقاً في فريق كرة يد؟ كيف تتعامل مع الأطفال، أليس لديك مشاكل مستمرة مع الانضباط؟ وكم عمر الأطفال الذين تدربهم بالضبط؟\nأسأل لأنني أعاني حالياً من ضغط كبير في حصة الرياضة التي أدرّسها.\nتعرف أنني بدأت دراسة الرياضة، أليس كذلك؟ حسناً، في الجامعة سار كل شيء على ما يرام حتى الآن، لكن أثناء التدريب المدرسي لم أنجح ببساطة في فرض احترامي على مجموعة من عشرين ولداً في الرابعة عشرة. كانوا صاخبين جداً ولم يفعلوا سوى ما أرادوه. انتهت الحصة في فوضى تامة.\nلذلك أعيش الآن أزمة متوسطة ولا أستطيع أن أتخيل نفسي أصبح معلماً على الإطلاق.\nلكن ربما لديك بعض النصائح والحيل لي، كيف يمكن للمرء أن يحظى باحترام مجموعة من المراهقين؟\n\nأرجو أن تكتب لي بسرعة!\n\nإذن أتمنى أن نلتقي قريباً\n\nصديقك المتضايق قليلاً ماتياس",
  "067c186b-1365-4d5a-9233-2e54fa7377f9": "مرحباً يوديت أو لينا\n\nلم نلتقِ منذ فترة طويلة. أتمنى أن تكوني قضيت عطلة جميلة حقاً في كرواتيا! شكراً أيضاً على بطاقتك من العطلة! لقد جعلتني أشعر بالغيرة الحقيقية؛ لن تكون لدي عطلة إلا في سبتمبر.\nنأمل أن تفتحي بريدك الإلكتروني اليوم بالفعل وتقرئي هذه الرسالة!\n\nنحن، كامل الفريق، نود أن نهدي زميلتنا إيلينا معاً هدية وداع بمناسبة تقاعدها. حفل وداعها هو بعد غد مساءً بالفعل في قاعة الاجتماعات الكبيرة في شركتنا. هل توافقين على أن نهديها معاً قسيمة وباقة ورد؟ كل شخص يدفع حوالي 10 يورو. أعتقد أن هذا مناسب. تتذكرين: عندما جمعنا التبرعات آخر مرة، كانت هناك شكاوى بخصوص مبلغ المساهمة. لكن ربما لديك فكرة أفضل.\n\nسأذهب أنا وميشائيل بعد الظهر للتسوق معاً في المدينة. يمكنك حينها التوقيع على بطاقة التهنئة لإيلينا بعد غد قبل الحفل بقليل. سنلتقي جميعاً قبل ذلك ونذهب معاً.\n\nلم يكن هناك الكثير في الشركة اليوم. لكن في الأيام الـ14 الماضية كان الكثير من الزملاء في إجازة، الأمر الذي جعلني مشغولة جداً. بالمناسبة هناك أيضاً تطورات جديدة تماماً في الشركة، سأخبرك عنها بعد غد.\nمن المحتمل أنك متعبة جداً بعد الرحلة الطويلة. نامي جيداً غداً؛ نراك في حفل إيلينا! أتمنى لك يوماً ممتعاً اليوم...\n\nتحياتي\nكوزيما",
  "2e4cb5d1-1205-44af-b53c-8b845b21abbe": "عزيزتي يوليا،\n\nأرسل لك تحياتي الحارة من باريس! أجلس الآن في مقهى مريح لكن مزدحم جداً بالقرب من متحف اللوفر وأستمتع بعطلتي. مضت الآن أشهر عدة منذ آخر تواصل بيننا. أتمنى أن تكوني بخير.\nأقوم حالياً بجولة عبر أوروبا كنت قد خططت لها منذ فترة. كما تعلمين، عملت كثيراً جداً في العامين الماضيين ولم أستطع أخذ إجازة إلا نادراً. بعد كل هذا الضغط، كان علي بالتأكيد أخذ استراحة أطول. بفضل ساعاتي الإضافية المتراكمة يمكنني الآن أخذ ثمانية أسابيع إجازة متتالية. لم يكن رئيسي متحمساً في البداية لهذه الفكرة، لكن في النهاية استطعت إقناعه. في أشهر الصيف يكون الجو هادئاً نسبياً في الشركة على أي حال. الآن أزور تدريجياً كل المدن الموجودة على قائمة وجهات أحلامي. أسافر فقط بالقطار أو الحافلة، لأنني لا أحب الطيران كثيراً. كانت أول محطة لي أمستردام، ثم مررت عبر بروكسل إلى باريس، وقريباً سأسافر أكثر نحو الجنوب. لا يفتقدني روتين المكتب إطلاقاً. لا أريد حتى التفكير في أنني سأعود يوماً ما حتماً إلى المكتب. في الأيام الأخيرة خطرت لي أحياناً فكرة أنني قد أبدأ شيئاً جديداً تماماً بعد عودتي... أتمنى لك صيفاً جميلاً!\nتحياتي الحارة وإلى اللقاء قريباً\nيوديت",
  "c94ca060-b403-4762-8da3-3e5e0894546d": "عزيزي يوليان،\n\nكيف حالك؟ أتمنى أنك قضيت رحلة جميلة وتمكنت من الاستراحة جيداً. أنا أيضاً أود السفر إلى البحر مرة أخرى، لكن ليس لدي وقت للعطلة حالياً للأسف. كما يمكنك أن تتخيل بالتأكيد، كنت في الأسابيع الماضية مشغولة بشكل أساسي بانتقالي. تعرف أنني كنت متشككة جداً في البداية؛ بعد سنوات عديدة في برلين لم أستطع أن أتخيل الاستقرار في مدينة صغيرة مثل بامبيرغ.\n\nليس لدى بامبيرغ سوى حوالي 77000 نسمة، لكنها ليست مملة رغم ذلك، كما اكتشفت مع مرور الوقت. الآن أشعر هنا بالراحة الحقيقية. تقدم المدينة الكثير حقاً. توجد معالم عمرها قرون بكثرة، وفي البلدة القديمة تعجبني بشكل خاص البيوت ذات الهياكل الخشبية الجميلة، التي يعود معظمها للعصور الوسطى. أمشي كثيراً في المنطقة المشاة، لأن هناك محلات ومقاهي ومطاعم صغيرة كثيرة بأطباق فرانكونية نموذجية. أعتقد أن المكان سيعجبك أيضاً. إذا أردت، سأريك المدينة بسرور. هل ترغب في زيارتي الشهر القادم؟ حينها ستكون ضغوط الانتقال قد انتهت أيضاً. حالياً لا يزال هناك عدد كبير من الصناديق غير المفرغة في غرفة معيشتي، يجب تفريغها. حالفني الحظ أيضاً في شقتي الجديدة، لأنها واسعة ومركزية الموقع. يمكننا التحدث هاتفياً، سأخبرك بالمزيد حينها.\n\nتحياتي\nآنا",
};

const merged = {};
for (const [exId, gaps] of Object.entries(explanations)) {
  merged[exId] = {
    translation: { text: passageTranslations[exId] },
    items: {},
  };
  for (const [gapNum, data] of Object.entries(gaps)) {
    merged[exId].items[gapNum] = {
      evidence_text: null,
      keyword: data.kw,
      explanation_correct: data.ex,
      explanation_wrong: data.ex,
      grammar_structure: data.gs,
      grammar_example: null,
      grammar_translation: null,
    };
  }
}

const ABBREV_ENDINGS = ["d.h.", "z.B.", "u.a.", "usw.", "bzw.", "ca.", "etc.", "Nr.", "Str.", "Dr.", "Mag.", "Prof."];
function isRealBoundary(text, i) {
  if (text[i] !== ".") return false;
  const after = text[i + 1];
  if (after !== undefined && after !== " " && after !== "\n") return false;
  const before = text.slice(Math.max(0, i - 8), i + 1);
  if (ABBREV_ENDINGS.some((a) => before.endsWith(a))) return false;
  if (/\d\.$/.test(before.slice(-2))) return false;
  return true;
}
function sentenceAround(passage, markerIdx, markerLen) {
  let start = 0;
  for (let i = markerIdx - 1; i >= 0; i--) {
    if (passage[i] === "\n") { start = i + 1; break; }
    if (isRealBoundary(passage, i)) { start = i + 1; break; }
  }
  let end = passage.length;
  for (let i = markerIdx + markerLen; i < passage.length; i++) {
    if (passage[i] === "\n") { end = i; break; }
    if (isRealBoundary(passage, i)) { end = i + 1; break; }
  }
  return passage.slice(start, end).trim().replace(/\s+/g, " ");
}

for (const [exId, aids] of Object.entries(merged)) {
  const src = passageData[exId];
  if (!src) { console.error("no source for", exId); continue; }
  const gapByNum = {};
  for (const g of src.gaps) gapByNum[g.gap_number] = g;
  for (const gap of src.gaps) {
    const k = String(gap.gap_number);
    const item = aids.items[k];
    if (!item) continue;
    const marker = `{{${k}}}`;
    const markerIdx = src.passage.indexOf(marker);
    if (markerIdx === -1) { console.error("marker not found", exId, k); continue; }
    let snippet = sentenceAround(src.passage, markerIdx, marker.length);
    snippet = snippet.replace(/\{\{(\d+)\}\}/g, (m, num) => {
      const g = gapByNum[Number(num)];
      return g ? g[`option_${g.correct}`] : m;
    });
    item.evidence_text = snippet;
  }
}

writeFileSync(
  "C:/Users/asus/AuraLingovia/scripts/learning-aids/sb_t1_batch4.json",
  JSON.stringify(merged)
);
console.log("Wrote sb_t1_batch4.json for", Object.keys(merged).length, "exercises");

let issues = 0;
for (const [exId, aids] of Object.entries(merged)) {
  const src = passageData[exId];
  if (!src) { issues++; continue; }
  if (!aids.translation.text) { console.error("missing translation", exId); issues++; }
  for (const gap of src.gaps) {
    const k = String(gap.gap_number);
    const item = aids.items[k];
    if (!item || !item.keyword || !item.explanation_correct || item.explanation_correct.length < 30 || item.evidence_text.includes("{{")) {
      console.error("incomplete/bad", exId, k);
      issues++;
    }
  }
}
console.log("issues:", issues);
